'use client';
import cl from "clsx/lite";
import { forwardRef } from "react";
import { jsx } from "react/jsx-runtime";
//#region src/components/badge/badge.tsx
/**
* `Badge` is a non-interactive component for displaying status with or without numbers.
*
* @example without children
* <Badge count={5} maxCount={10} />
*
* @example with children
* <Badge count={5} maxCount={10}>
*   <Icon />
* </Badge>
*/
const Badge = forwardRef(function Badge({ className, count, maxCount, variant, ...rest }, ref) {
	return /* @__PURE__ */ jsx("span", {
		className: cl("ds-badge", className),
		"data-count": count && maxCount && count > maxCount ? `${maxCount}+` : count,
		"data-variant": variant,
		ref,
		...rest
	});
});
//#endregion
export { Badge };
